import{_ as e,o,c as a,a2 as r}from"./chunks/framework.DGk0zlJw.js";const b=JSON.parse('{"title":"Beacon 隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh/privacy-policy.md","filePath":"zh/privacy-policy.md"}'),d={name:"zh/privacy-policy.md"};function n(c,t,i,s,l,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="beacon-隐私政策" tabindex="-1">Beacon 隐私政策 <a class="header-anchor" href="#beacon-隐私政策" aria-label="Permalink to &quot;Beacon 隐私政策&quot;">​</a></h1><p>最后更新：2026-10-12 · 适用版本：v0.1.x（含每日构建）</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>Beacon 不收集、不上传任何数据到开发者的服务器。</strong> 所有数据只存在你自己的电脑上；网络请求只发往你自己配置的 API 端点和本项目官方仓库的更新检查接口。</p><h2 id="收集哪些数据" tabindex="-1">收集哪些数据 <a class="header-anchor" href="#收集哪些数据" aria-label="Permalink to &quot;收集哪些数据&quot;">​</a></h2><p>Beacon 在<strong>你的电脑本地</strong>保存三类数据，全部由你自己录入或由本机运行产生：</p><table tabindex="0"><thead><tr><th>类别</th><th>内容</th><th>来源</th></tr></thead><tbody><tr><td>凭据</td><td>GitHub PAT、各 AI 平台 API key（智谱 / Kimi / DeepSeek / 火山方舟 / 阿里千问 / 小米 MiMo / Claude / Codex / Copilot / OpenCode 等，按你配置的连接而定）</td><td>你在设置页录入</td></tr><tr><td>配置</td><td>连接配置、刷新间隔、主题、组件与钉选布局、动作（含可选 webhook）</td><td>你在设置页调整</td></tr><tr><td>本机状态读数</td><td>CPU / 内存 / 磁盘 / 网络速率 / IP 地址等，仅用于本地展示</td><td>本机采样</td></tr></tbody></table><p>Beacon <strong>没有</strong>账号体系，<strong>没有</strong>遥测或埋点，<strong>不</strong>向开发者或任何第三方上报任何数据。</p><h2 id="数据存在哪里" tabindex="-1">数据存在哪里 <a class="header-anchor" href="#数据存在哪里" aria-label="Permalink to &quot;数据存在哪里&quot;">​</a></h2><p>全部在本机用户目录 <code>%AppData%\\Beacon\\</code>（即 <code>%APPDATA%\\Beacon</code>，普通用户态，无需管理员）：</p><table tabindex="0"><thead><tr><th>文件 / 目录</th><th>内容</th><th>保护方式</th></tr></thead><tbody><tr><td><code>secrets.bin</code></td><td>所有凭据</td><td><strong>DPAPI（CurrentUser）加密</strong>——只能被同一 Windows 账户解密，文件本身不含明文</td></tr><tr><td><code>connections.json</code></td><td>连接配置</td><td><strong>不含明文凭据</strong>：只存 credentialRef 引用，密钥本体在 <code>secrets.bin</code></td></tr><tr><td><code>config.json</code> / <code>widgets.json</code> / <code>pins.json</code> / <code>actions.json</code></td><td>全局设置 / 组件 / 钉选 / 动作</td><td>明文 JSON，不含凭据</td></tr><tr><td><code>cache\\</code></td><td>各组件最近一次状态缓存</td><td>明文 JSON</td></tr><tr><td><code>notifications.json</code></td><td>通知历史与已读态</td><td>明文 JSON</td></tr><tr><td><code>logs\\</code></td><td>运行日志</td><td>明文文本（排障用）</td></tr></tbody></table><p>配置的导入导出包<strong>永远不包含凭据</strong>——导出文件里只有 credentialRef 引用，换机后需重新录入密钥。</p><h2 id="数据如何离开本机" tabindex="-1">数据如何离开本机 <a class="header-anchor" href="#数据如何离开本机" aria-label="Permalink to &quot;数据如何离开本机&quot;">​</a></h2><p>Beacon 主动发出的网络请求只有三类，全部可预期、可关闭：</p><ol><li><strong>更新检查</strong>（默认开启，暂无开关）：启动 20 秒后向本项目的公开仓库接口 <code>api.github.com/repos/cuihairu/beacon/releases/latest</code> 发一次 GET（进程生命周期内只查一次，手动「检查更新」按钮可强刷）——请求里只有 User-Agent（<code>Beacon-Update-Check</code>）与你的 IP（任何网络请求都会携带），<strong>不含任何个人数据</strong>。</li><li><strong>连接查询</strong>：只发往<strong>你自己配置</strong>的 API 端点（GitHub API、各 AI 平台控制台/用量端点），鉴权用你自己录入的 key。你配置哪些连接，Beacon 就联系哪些端点；删掉连接即停止。</li><li><strong>动作</strong>：仅当你自己配置了 HTTP / webhook 动作时，才会向你指定的 URL 发请求（webhook 带 HMAC-SHA256 签名头，密钥同样只进 DPAPI）。</li></ol><p>除以上三类外，Beacon 不建立任何其他网络连接。</p><h2 id="数据用途" tabindex="-1">数据用途 <a class="header-anchor" href="#数据用途" aria-label="Permalink to &quot;数据用途&quot;">​</a></h2><p>本地数据只用于：在屏幕上展示状态（胶囊、悬浮组件、快速面板）、执行你配置的本地动作、维护设置与通知历史。凭据只用于向对应平台鉴权查询，不做任何其他用途。</p><h2 id="保留与删除" tabindex="-1">保留与删除 <a class="header-anchor" href="#保留与删除" aria-label="Permalink to &quot;保留与删除&quot;">​</a></h2><ul><li>数据随安装目录存续；卸载走系统「添加或删除程序」（或直接删除便携包目录），再删除 <code>%AppData%\\Beacon\\</code> 即可<strong>彻底清除全部本地数据</strong>，包括加密凭据。</li><li>Beacon 没有云端副本——删了就是删了。</li><li>配置页的「导入/导出」只搬运配置（不含凭据），不影响本条。</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>对本政策或数据处理有疑问：</p><ul><li>GitHub：<a href="https://github.com/cuihairu" target="_blank" rel="noreferrer">github.com/cuihairu</a>（项目仓库 <a href="https://github.com/cuihairu/beacon" target="_blank" rel="noreferrer">cuihairu/beacon</a> 提 issue 即可）</li></ul>',23)])])}const u=e(d,[["render",n]]);export{b as __pageData,u as default};
